import pandas as pd
import numpy as np

try:
    arr = np.array([np.nan, 1.0])
    result = pd.array(arr, dtype='i8')
    probe('conversion_succeeded', 1.0)  # This should NOT happen on fixed
except Exception as e:
    probe('exception_raised', 1.0)
    if 'IntCastingNaNError' in type(e).__name__:
        probe('correct_exception', 1.0)

